/** Normalize list API (paged object or legacy array) for call sites. */
export function planVoucherListItems(
  data: PlanVoucherListPageDto | PlanVoucherDraftDto[] | unknown,
): PlanVoucherDraftDto[] {
  if (Array.isArray(data)) return data as PlanVoucherDraftDto[];
  if (data && typeof data === 'object' && Array.isArray((data as PlanVoucherListPageDto).items)) {
    return (data as PlanVoucherListPageDto).items;
  }
  return [];
}

export function planVoucherListPage(
  data: PlanVoucherListPageDto | PlanVoucherDraftDto[] | unknown,
  fallbackPage = 1,
  fallbackPageSize = 20,
): PlanVoucherListPageDto {
  if (Array.isArray(data)) {
    return {
      items: data as PlanVoucherDraftDto[],
      totalCount: data.length,
      page: fallbackPage,
      pageSize: fallbackPageSize,
    };
  }
  const d = data as Partial<PlanVoucherListPageDto> | null;
  const items = Array.isArray(d?.items) ? d.items : [];
  return {
    items,
    totalCount: typeof d?.totalCount === 'number' ? d.totalCount : items.length,
    page: typeof d?.page === 'number' ? d.page : fallbackPage,
    pageSize: typeof d?.pageSize === 'number' ? d.pageSize : fallbackPageSize,
  };
}

